/* **************************************** */
/*          INSTRUCCIONES INICIALES         */
/* **************************************** */
SET CLIENT_ENCODING TO 'UTF8';

/* **************************************** */
/*                  ESQUEMA                 */
/* **************************************** */
-- usuario
create table public.usuario (
  id bigint primary key not null,
  nombre character varying(100) not null,
  apellido character varying(100) not null,
  correo character varying(254) not null,
  contrasena character varying(100) not null
);
create unique index usuario_correo_key on usuario using btree (correo);
create index usuario_correo_like on usuario using btree (correo);

-- suscripcion
create table public.suscripcion (
  id bigint primary key not null,
  creador_id bigint not null references public.usuario (id) on update restrict on delete cascade,
  suscriptor_id bigint not null references public.usuario (id) on update restrict on delete cascade
);
create unique index suscripcion_suscriptor_id_creador_id_uniq on suscripcion using btree (suscriptor_id, creador_id);
create index suscripcion_creador_id on suscripcion using btree (creador_id);
create index suscripcion_suscriptor_id on suscripcion using btree (suscriptor_id);

-- videos
create table public.video (
  id bigint primary key not null,
  uuid uuid not null,
  titulo character varying(100) not null,
  descripcion text not null,
  fecha_creacion timestamp with time zone not null,
  duracion smallint not null,
  creador_id bigint not null references public.usuario (id) on update restrict on delete cascade
);
create unique index video_uuid_key on video using btree (uuid);
create index video_creador_id on video using btree (creador_id);

-- reproducciones
create table public.reproduccion (
  id bigint primary key not null,
  fecha_reproduccion timestamp with time zone not null,
  dispositivo_reproduccion character varying(100) not null,
  usuario_id bigint not null references public.usuario (id) on update restrict on delete cascade,
  video_id bigint not null references public.video (id) on update restrict on delete cascade
);
create index reproduccion_usuario_id on reproduccion using btree (usuario_id);
create index reproduccion_video_id on reproduccion using btree (video_id);

-- comentarios
create table public.comentario (
  id bigint primary key not null,
  contenido text not null,
  fecha_creacion timestamp with time zone not null,
  usuario_id bigint not null references public.usuario (id) on update restrict on delete cascade,
  video_id bigint not null references public.video (id) on update restrict on delete cascade
);
create index comentario_usuario_id on comentario using btree (usuario_id);
create index comentario_video_id on comentario using btree (video_id);

/* **************************************** */
/*                  SECUENCIAS              */
/* **************************************** */
-- usuario
create sequence usuario_id_seq;
alter sequence usuario_id_seq owned by usuario.id;
alter sequence usuario_id_seq restart with 2001;
alter table usuario alter column id set default nextval('usuario_id_seq');

-- suscripcion
create sequence suscripcion_id_seq;
alter sequence suscripcion_id_seq owned by suscripcion.id;
alter sequence suscripcion_id_seq restart with 14938;
alter table suscripcion alter column id set default nextval('suscripcion_id_seq');

-- video
create sequence video_id_seq;
alter sequence video_id_seq owned by video.id;
alter sequence video_id_seq restart with 4691;
alter table video alter column id set default nextval('video_id_seq');

-- reproduccion
create sequence reproduccion_id_seq;
alter sequence reproduccion_id_seq owned by reproduccion.id;
alter sequence reproduccion_id_seq restart with 50424;
alter table reproduccion alter column id set default nextval('reproduccion_id_seq');

-- comentario
create sequence comentario_id_seq;
alter sequence comentario_id_seq owned by comentario.id;
alter sequence comentario_id_seq restart with 30087;
alter table comentario alter column id set default nextval('comentario_id_seq');


/* **************************************** */
/*                     DATOS                */
/* **************************************** */
